/* THEME MANAGEMENT SYSTEM */
function setTheme(theme) {
  if (theme === 'dark') {
    document.documentElement.setAttribute('data-theme', 'dark');
  } else {
    document.documentElement.removeAttribute('data-theme');
  }
  try { localStorage.setItem('wd_theme', theme); } catch (e) {}
  updateThemeUI(theme);
}

function updateThemeUI(theme) {
  var themeBtn = document.getElementById('wdThemeToggleBtn');
  if (!themeBtn) return;
  var iconMoon = themeBtn.querySelector('.icon-moon');
  var iconSun = themeBtn.querySelector('.icon-sun');
  if (theme === 'dark') {
    if (iconMoon) iconMoon.style.display = 'none';
    if (iconSun) iconSun.style.display = 'block';
    themeBtn.setAttribute('aria-label', 'Switch to Light Mode');
    themeBtn.setAttribute('title', 'Switch to Light Mode');
  } else {
    if (iconMoon) iconMoon.style.display = 'block';
    if (iconSun) iconSun.style.display = 'none';
    themeBtn.setAttribute('aria-label', 'Switch to Dark Mode');
    themeBtn.setAttribute('title', 'Switch to Dark Mode');
  }
}

/* LANGUAGE & TRANSLATION SYSTEM */
function setLanguage(lang) {
  if (!translations[lang]) lang = 'en';
  try { localStorage.setItem('wd_lang', lang); } catch (e) {}
  document.documentElement.setAttribute('lang', lang);

  // Update Header Label
  var labelEl = document.getElementById('wdLangCurrentLabel');
  if (labelEl) {
    labelEl.textContent = lang === 'hi' ? 'HI' : 'EN';
  }

  // Update Option Checkmarks
  var optionBtns = document.querySelectorAll('.wd-lang-option-btn');
  optionBtns.forEach(function(btn) {
    var btnLang = btn.getAttribute('data-lang');
    if (btnLang === lang) {
      btn.classList.add('selected');
    } else {
      btn.classList.remove('selected');
    }
  });

  // Update data-i18n elements
  var i18nElements = document.querySelectorAll('[data-i18n]');
  i18nElements.forEach(function(el) {
    var key = el.getAttribute('data-i18n');
    if (translations[lang] && translations[lang][key]) {
      el.textContent = translations[lang][key];
    }
  });

  // Notify Showcase & Hero of language update if available
  if (window.onLanguageChanged) {
    window.onLanguageChanged(lang);
  }
}

/* MAIN DOM INITIALIZATION */
document.addEventListener('DOMContentLoaded', function() {
  // 1. Header Scroll Effect
  var header = document.getElementById('siteHeader');
  if (header) {
    window.addEventListener('scroll', function() {
      if (window.scrollY > 40) {
        header.classList.add('scrolled');
      } else {
        header.classList.remove('scrolled');
      }
    });
  }

  // 2. Theme Toggle Listener
  var themeBtn = document.getElementById('wdThemeToggleBtn');
  var initialTheme = document.documentElement.getAttribute('data-theme') === 'dark' ? 'dark' : 'light';
  updateThemeUI(initialTheme);

  if (themeBtn) {
    themeBtn.addEventListener('click', function() {
      var activeTheme = document.documentElement.getAttribute('data-theme') === 'dark' ? 'dark' : 'light';
      var nextTheme = activeTheme === 'dark' ? 'light' : 'dark';
      setTheme(nextTheme);
    });
  }

  // 3. Language Selector Dropdown Listener
  var langWrap = document.getElementById('wdLangDropdownWrap');
  var langBtn = document.getElementById('wdLangToggleBtn');
  var initialLang = localStorage.getItem('wd_lang') || 'en';
  setLanguage(initialLang);

  if (langBtn && langWrap) {
    langBtn.addEventListener('click', function(e) {
      e.stopPropagation();
      var isOpen = langWrap.classList.contains('open');
      if (isOpen) {
        langWrap.classList.remove('open');
        langBtn.setAttribute('aria-expanded', 'false');
      } else {
        langWrap.classList.add('open');
        langBtn.setAttribute('aria-expanded', 'true');
      }
    });

    document.querySelectorAll('.wd-lang-option-btn').forEach(function(btn) {
      btn.addEventListener('click', function(e) {
        e.stopPropagation();
        var selectedLang = this.getAttribute('data-lang');
        setLanguage(selectedLang);
        langWrap.classList.remove('open');
        if (langBtn) langBtn.setAttribute('aria-expanded', 'false');
      });
    });

    document.addEventListener('click', function(e) {
      if (!langWrap.contains(e.target)) {
        langWrap.classList.remove('open');
        if (langBtn) langBtn.setAttribute('aria-expanded', 'false');
      }
    });

    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape') {
        langWrap.classList.remove('open');
        if (langBtn) langBtn.setAttribute('aria-expanded', 'false');
      }
    });
  }

  // 4. Mobile Navigation Drawer
  var menuToggle = document.getElementById('menuToggle');
  var navMenu = document.getElementById('navMenu');
  var menuBackdrop = document.getElementById('menuBackdrop');

  function closeMobileMenu() {
    if (menuToggle) menuToggle.classList.remove('active');
    if (navMenu) navMenu.classList.remove('active');
    if (menuBackdrop) menuBackdrop.classList.remove('active');
    document.body.style.overflow = '';
  }

  if (menuToggle && navMenu && menuBackdrop) {
    menuToggle.addEventListener('click', function(e) {
      e.stopPropagation();
      var isActive = menuToggle.classList.contains('active');
      if (isActive) {
        closeMobileMenu();
      } else {
        menuToggle.classList.add('active');
        navMenu.classList.add('active');
        menuBackdrop.classList.add('active');
        document.body.style.overflow = 'hidden';
      }
    });

    menuBackdrop.addEventListener('click', closeMobileMenu);

    var navLinks = navMenu.querySelectorAll('a');
    navLinks.forEach(function(link) {
      link.addEventListener('click', closeMobileMenu);
    });

    window.addEventListener('keydown', function(e) {
      if (e.key === 'Escape') closeMobileMenu();
    });
  }

  // 5. Dynamic Hero Benefit Phrase Rotation
  (function setupHeroRotation() {
    var phraseEl = document.getElementById('heroRotatingPhrase');
    if (!phraseEl) return;
    var currentIndex = 0;
    var prefersReducedMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    if (prefersReducedMotion) return;

    setInterval(function() {
      var currentLang = localStorage.getItem('wd_lang') || 'en';
      var phrases = currentLang === 'hi' ? [
        'हर दिन हाजिरी लगाएं',
        'व्यवस्थित रहें',
        'अपनी कमाई जानें',
        'ओवरटाइम ट्रैक करें',
        'आपका दैनिक रिकॉर्ड',
        'काम। रिकॉर्ड। हिसाब।'
      ] : [
        'Track Every Day',
        'Stay Organized',
        'Know Your Earnings',
        'Track Overtime',
        'Your Daily Records',
        'Work. Track. Know.'
      ];

      phraseEl.classList.add('fade-out');
      setTimeout(function() {
        currentIndex = (currentIndex + 1) % phrases.length;
        phraseEl.textContent = phrases[currentIndex];
        phraseEl.classList.remove('fade-out');
        phraseEl.classList.add('fade-in');
        requestAnimationFrame(function() {
          requestAnimationFrame(function() {
            phraseEl.classList.remove('fade-in');
          });
        });
      }, 350);
    }, 2800);
  })();

  // 6. Custom WorkDaily Video Players Engine
  (function setupCustomVideoPlayers() {
    window.WorkDailyVideoRegistry = window.WorkDailyVideoRegistry || {
      videos: [],
      register: function(video) {
        if (!video || video.getAttribute('data-wd-registered') === 'true') return;
        video.setAttribute('data-wd-registered', 'true');
        this.videos.push(video);
        video.addEventListener('play', function() {
          window.WorkDailyVideoRegistry.pauseOthers(video);
        });
      },
      pauseOthers: function(currentVid) {
        this.videos.forEach(function(v) {
          if (v !== currentVid && !v.paused) {
            try { v.pause(); } catch(e) {}
          }
        });
      }
    };

    function formatTime(seconds) {
      if (isNaN(seconds) || seconds < 0) return '0:00';
      var mins = Math.floor(seconds / 60);
      var secs = Math.floor(seconds % 60);
      return mins + ':' + (secs < 10 ? '0' : '') + secs;
    }

    function initVideoPlayer(wrapper) {
      if (!wrapper || wrapper.getAttribute('data-wd-initialized') === 'true') return;
      wrapper.setAttribute('data-wd-initialized', 'true');

      var video = wrapper.querySelector('.custom-video-element');
      if (!video) return;

      window.WorkDailyVideoRegistry.register(video);

      var centerPlayBtn = wrapper.querySelector('.video-center-play-btn');
      var loaderOverlay = wrapper.querySelector('.video-loader-overlay');
      var errorOverlay = wrapper.querySelector('.video-error-overlay');
      var retryBtn = wrapper.querySelector('.video-retry-btn');
      var btnMute = wrapper.querySelector('.btn-mute');
      var btnFullscreen = wrapper.querySelector('.btn-fullscreen');
      var seekbarContainer = wrapper.querySelector('.custom-seekbar-container');
      var seekbarProgress = wrapper.querySelector('.custom-seekbar-progress');
      var timeCurrent = wrapper.querySelector('.time-current');
      var timeDuration = wrapper.querySelector('.time-duration');
      var tapZones = wrapper.querySelectorAll('.video-tap-zone');
      var feedbackLeft = wrapper.querySelector('.video-seek-feedback-left');
      var feedbackRight = wrapper.querySelector('.video-seek-feedback-right');

      var userRequestedPlay = false;

      if (loaderOverlay) loaderOverlay.style.display = 'none';
      if (errorOverlay) errorOverlay.style.display = 'none';

      function showLoader(msg) {
        if (loaderOverlay && userRequestedPlay) {
          var txt = loaderOverlay.querySelector('.video-loader-text') || loaderOverlay.querySelector('span');
          if (txt) txt.textContent = msg || 'Loading video...';
          loaderOverlay.style.display = 'flex';
        }
      }

      function hideLoader() {
        if (loaderOverlay) loaderOverlay.style.display = 'none';
      }

      function showError() {
        hideLoader();
        if (errorOverlay) errorOverlay.style.display = 'flex';
        updatePlayUI();
      }

      function hideError() {
        if (errorOverlay) errorOverlay.style.display = 'none';
      }

      function updatePlayUI() {
        if (video.paused || video.ended) {
          wrapper.classList.remove('playing');
          if (centerPlayBtn) {
            var playIcon = centerPlayBtn.querySelector('.icon-play');
            var pauseIcon = centerPlayBtn.querySelector('.icon-pause');
            if (playIcon) playIcon.style.display = 'block';
            if (pauseIcon) pauseIcon.style.display = 'none';
          }
        } else {
          wrapper.classList.add('playing');
          if (centerPlayBtn) {
            var playIcon = centerPlayBtn.querySelector('.icon-play');
            var pauseIcon = centerPlayBtn.querySelector('.icon-pause');
            if (playIcon) playIcon.style.display = 'none';
            if (pauseIcon) pauseIcon.style.display = 'block';
          }
        }
      }

      function togglePlay() {
        if (video.paused || video.ended) {
          userRequestedPlay = true;
          hideError();
          if (video.readyState < 3) {
            showLoader('Buffering...');
          }
          var playPromise = video.play();
          if (playPromise !== undefined) {
            playPromise.then(function() {
              hideLoader();
              hideError();
              updatePlayUI();
            }).catch(function(err) {
              console.log('Video play error handled:', err);
              hideLoader();
              updatePlayUI();
            });
          }
        } else {
          video.pause();
        }
      }

      function updateMuteUI() {
        if (!btnMute) return;
        var volIcon = btnMute.querySelector('.icon-volume');
        var mutedIcon = btnMute.querySelector('.icon-muted');
        if (video.muted) {
          if (volIcon) volIcon.style.display = 'none';
          if (mutedIcon) mutedIcon.style.display = 'block';
        } else {
          if (volIcon) volIcon.style.display = 'block';
          if (mutedIcon) mutedIcon.style.display = 'none';
        }
      }

      function showFeedback(element) {
        if (!element) return;
        element.classList.add('active');
        setTimeout(function() {
          element.classList.remove('active');
        }, 600);
      }

      video.addEventListener('waiting', function() {
        if (userRequestedPlay) showLoader('Buffering...');
      });

      video.addEventListener('stalled', function() {
        if (userRequestedPlay && !video.paused) showLoader('Buffering...');
      });

      video.addEventListener('canplay', function() {
        hideLoader();
      });

      video.addEventListener('canplaythrough', function() {
        hideLoader();
      });

      video.addEventListener('playing', function() {
        hideLoader();
        hideError();
        updatePlayUI();
      });

      video.addEventListener('pause', function() {
        hideLoader();
        updatePlayUI();
      });

      video.addEventListener('ended', function() {
        userRequestedPlay = false;
        hideLoader();
        updatePlayUI();
      });

      video.addEventListener('error', function() {
        showError();
      });

      if (retryBtn) {
        retryBtn.addEventListener('click', function(e) {
          e.stopPropagation();
          userRequestedPlay = true;
          hideError();
          showLoader('Loading video...');
          try {
            video.load();
            var p = video.play();
            if (p && p.catch) {
              p.catch(function(err) {
                console.warn('[WorkDaily Retry Play Rejected]', err);
                updatePlayUI();
                showError();
              });
            }
          } catch(err) {
            console.warn('[WorkDaily Retry Exception]', err);
            showError();
          }
        });
      }

      if (centerPlayBtn) {
        centerPlayBtn.addEventListener('click', function(e) {
          e.stopPropagation();
          togglePlay();
        });
      }

      var tapTimer = null;
      var lastTapTime = 0;
      var lastZone = null;

      tapZones.forEach(function(zone) {
        zone.addEventListener('click', function(e) {
          e.stopPropagation();
          var zoneName = zone.getAttribute('data-zone');
          var now = Date.now();
          var timeDiff = now - lastTapTime;

          if (lastZone === zoneName && timeDiff < 300) {
            clearTimeout(tapTimer);
            tapTimer = null;

            if (zoneName === 'left') {
              video.currentTime = Math.max(0, video.currentTime - 10);
              showFeedback(feedbackLeft);
            } else if (zoneName === 'right') {
              video.currentTime = Math.min(video.duration || 0, video.currentTime + 10);
              showFeedback(feedbackRight);
            } else {
              togglePlay();
            }
          } else {
            tapTimer = setTimeout(function() {
              togglePlay();
            }, 300);
          }

          lastTapTime = now;
          lastZone = zoneName;
        });
      });

      if (btnMute) {
        btnMute.addEventListener('click', function(e) {
          e.stopPropagation();
          video.muted = !video.muted;
          updateMuteUI();
        });
      }

      if (btnFullscreen) {
        btnFullscreen.addEventListener('click', function(e) {
          e.stopPropagation();
          if (!document.fullscreenElement) {
            if (wrapper.requestFullscreen) {
              wrapper.requestFullscreen();
            } else if (wrapper.webkitRequestFullscreen) {
              wrapper.webkitRequestFullscreen();
            }
          } else {
            if (document.exitFullscreen) {
              document.exitFullscreen();
            } else if (document.webkitExitFullscreen) {
              document.webkitExitFullscreen();
            }
          }
        });
      }

      video.addEventListener('loadedmetadata', function() {
        if (timeDuration) timeDuration.textContent = formatTime(video.duration);
      });

      video.addEventListener('timeupdate', function() {
        if (timeCurrent) timeCurrent.textContent = formatTime(video.currentTime);
        if (timeDuration && video.duration) timeDuration.textContent = formatTime(video.duration);
        if (seekbarProgress && video.duration) {
          var pct = (video.currentTime / video.duration) * 100;
          seekbarProgress.style.width = pct + '%';
        }
      });

      if (seekbarContainer) {
        var isDragging = false;
        function seek(e) {
          if (!video.duration) return;
          var rect = seekbarContainer.getBoundingClientRect();
          var clientX = e.clientX || (e.touches && e.touches[0] ? e.touches[0].clientX : 0);
          var pos = (clientX - rect.left) / rect.width;
          pos = Math.max(0, Math.min(1, pos));
          video.currentTime = pos * video.duration;
        }

        seekbarContainer.addEventListener('mousedown', function(e) {
          isDragging = true;
          seek(e);
        });

        window.addEventListener('mousemove', function(e) {
          if (isDragging) seek(e);
        });

        window.addEventListener('mouseup', function() {
          isDragging = false;
        });

        seekbarContainer.addEventListener('touchstart', function(e) {
          isDragging = true;
          seek(e);
        }, { passive: true });

        window.addEventListener('touchmove', function(e) {
          if (isDragging) seek(e);
        }, { passive: true });

        window.addEventListener('touchend', function() {
          isDragging = false;
        });
      }

      wrapper.addEventListener('keydown', function(e) {
        if (e.key === ' ' || e.key === 'k') {
          e.preventDefault();
          togglePlay();
        } else if (e.key === 'ArrowLeft') {
          e.preventDefault();
          video.currentTime = Math.max(0, video.currentTime - 10);
          showFeedback(feedbackLeft);
        } else if (e.key === 'ArrowRight') {
          e.preventDefault();
          video.currentTime = Math.min(video.duration || 0, video.currentTime + 10);
          showFeedback(feedbackRight);
        } else if (e.key === 'm') {
          e.preventDefault();
          video.muted = !video.muted;
          updateMuteUI();
        } else if (e.key === 'f') {
          e.preventDefault();
          if (btnFullscreen) btnFullscreen.click();
        }
      });
    }

    function enhanceArticleVideos() {
      var articleVideos = document.querySelectorAll('.wd-article-body video, .post-body video');
      articleVideos.forEach(function(vid) {
        if (vid.closest('.custom-video-wrapper')) return;

        vid.classList.add('custom-video-element');
        if (!vid.getAttribute('preload')) vid.setAttribute('preload', 'metadata');
        vid.setAttribute('playsinline', 'true');

        var wrapper = document.createElement('div');
        wrapper.className = 'custom-video-wrapper';
        wrapper.setAttribute('tabindex', '0');
        wrapper.setAttribute('aria-label', 'WorkDaily Article Video');

        vid.parentNode.insertBefore(wrapper, vid);
        wrapper.appendChild(vid);

        var controlsHTML = [
          '<div class="video-loader-overlay" style="display:none;">',
          '  <div class="video-loader-spinner"></div>',
          '  <span class="video-loader-text">Loading video...</span>',
          '</div>',
          '<div class="video-error-overlay" style="display:none;">',
          '  <svg class="video-error-icon" style="width:28px;height:28px;fill:#F87171;" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm1 15h-2v-2h2v2zm0-4h-2V7h2v6z"/></svg>',
          '  <span class="video-error-text">Video unavailable</span>',
          '  <span class="video-error-subtext">Unable to load this video.</span>',
          '  <button class="video-retry-btn" type="button">Retry</button>',
          '</div>',
          '<div class="video-tap-zones">',
          '  <div class="video-tap-zone video-tap-zone-left" data-zone="left"></div>',
          '  <div class="video-tap-zone video-tap-zone-center" data-zone="center"></div>',
          '  <div class="video-tap-zone video-tap-zone-right" data-zone="right"></div>',
          '</div>',
          '<button class="video-center-play-btn" aria-label="Play / Pause Video">',
          '  <svg class="icon-play" style="width:24px;height:24px;fill:currentColor;margin-left:2px;" viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg>',
          '  <svg class="icon-pause" style="width:24px;height:24px;fill:currentColor;display:none;" viewBox="0 0 24 24"><path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z"/></svg>',
          '</button>',
          '<div class="video-seek-feedback video-seek-feedback-left">',
          '  <svg style="width:20px;height:20px;fill:currentColor;" viewBox="0 0 24 24"><path d="M11 18V6l-8.5 6 8.5 6zm.5-6l8.5 6V6l-8.5 6z"/></svg>',
          '  <span>↶ 10 sec</span>',
          '</div>',
          '<div class="video-seek-feedback video-seek-feedback-right">',
          '  <svg style="width:20px;height:20px;fill:currentColor;" viewBox="0 0 24 24"><path d="M4 18l8.5-6L4 6v12zm9-12v12l8.5-6L13 6z"/></svg>',
          '  <span>↷ 10 sec</span>',
          '</div>',
          '<div class="custom-player-controls">',
          '  <div class="custom-seekbar-container" role="slider" aria-label="Seek Bar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0" tabindex="0">',
          '    <div class="custom-seekbar-track">',
          '      <div class="custom-seekbar-progress"></div>',
          '    </div>',
          '  </div>',
          '  <div class="custom-player-row">',
          '    <div class="custom-player-time"><span class="time-current">0:00</span> / <span class="time-duration">0:00</span></div>',
          '    <div class="custom-player-btn-group">',
          '      <button class="custom-player-btn btn-mute" aria-label="Mute">',
          '        <svg class="icon-volume" style="width:20px;height:20px;fill:currentColor;" viewBox="0 0 24 24"><path d="M3 9v6h4l5 5V4L7 9H3zm13.5 3c0-1.77-1.02-3.29-2.5-4.03v8.05c1.48-.73 2.5-2.25 2.5-4.02z"/></svg>',
          '        <svg class="icon-muted" style="width:20px;height:20px;fill:currentColor;display:none;" viewBox="0 0 24 24"><path d="M16.5 12c0-1.77-1.02-3.29-2.5-4.03v2.21l2.45 2.45c.03-.2.05-.41.05-.63zm2.5 0c0 .94-.2 1.82-.54 2.64l1.51 1.51C20.63 14.91 21 13.5 21 12c0-4.28-2.99-7.86-7-8.77v2.06c2.89.86 5 3.54 5 6.71zM4.27 3L3 4.27 7.73 9H3v6h4l5 5v-6.73l4.25 4.25c-.67.52-1.42.93-2.25 1.18v2.06c1.38-.31 2.63-.95 3.69-1.81L19.73 21 21 19.73l-9-9L4.27 3zM12 4L9.91 6.09 12 8.18V4z"/></svg>',
          '      </button>',
          '      <button class="custom-player-btn btn-fullscreen" aria-label="Fullscreen">',
          '        <svg class="icon-fullscreen-enter" style="width:20px;height:20px;fill:currentColor;" viewBox="0 0 24 24"><path d="M7 14H5v5h5v-2H7v-3zm-2-4h2V7h3V5H5v5zm12 7h-3v2h5v-5h-2v3zM14 5v2h3v3h2V5h-5z"/></svg>',
          '        <svg class="icon-fullscreen-exit" style="width:20px;height:20px;fill:currentColor;display:none;" viewBox="0 0 24 24"><path d="M5 16h3v3h2v-5H5v2zm3-8H5v2h5V5H8v3zm6 11h2v-3h3v-2h-5v5zm2-11V5h-2v5h5V8h-3z"/></svg>',
          '      </button>',
          '    </div>',
          '  </div>',
          '</div>'
        ].join('');

        wrapper.insertAdjacentHTML('beforeend', controlsHTML);
        initVideoPlayer(wrapper);
      });
    }

    function initAllVideoPlayers() {
      enhanceArticleVideos();
      var wrappers = document.querySelectorAll('.custom-video-wrapper');
      wrappers.forEach(function(w) {
        initVideoPlayer(w);
      });
    }

    window.initAllVideoPlayers = initAllVideoPlayers;
    initAllVideoPlayers();
  })();

  // 7. Unified Showcase Carousel Engine
  (function setupCarousel() {
    var carousel = document.querySelector('[data-carousel="unified-showcase"]');
    if (!carousel) return;

    var track = carousel.querySelector('[data-carousel-track="true"]');
    var slides = carousel.querySelectorAll('[data-carousel-slide="true"]');
    var prevBtn = carousel.querySelector('[data-carousel-prev="true"]');
    var nextBtn = carousel.querySelector('[data-carousel-next="true"]');
    var dotsContainer = carousel.querySelector('[data-carousel-dots="true"]');

    if (!track || slides.length === 0) return;

    var currentIndex = 0;

    // Build dots
    if (dotsContainer) {
      dotsContainer.innerHTML = '';
      slides.forEach(function(_, idx) {
        var dot = document.createElement('button');
        dot.className = 'wd-carousel-dot' + (idx === 0 ? ' active' : '');
        dot.setAttribute('aria-label', 'Go to screenshot ' + (idx + 1));
        dot.addEventListener('click', function() {
          goToSlide(idx);
        });
        dotsContainer.appendChild(dot);
      });
    }

    function updateShowcaseText(index) {
      var lang = localStorage.getItem('wd_lang') || 'en';
      var list = showcaseTranslations[lang] || showcaseTranslations['en'];
      var item = list[index] || list[0];

      var numEl = document.getElementById('showcaseSlideNum');
      var titleEl = document.getElementById('showcaseSlideTitle');
      var descEl = document.getElementById('showcaseSlideDesc');
      var chipsEl = document.getElementById('showcaseSlideChips');

      if (numEl) numEl.textContent = (index + 1) + ' / ' + slides.length;
      if (titleEl) titleEl.textContent = item.title;
      if (descEl) descEl.textContent = '"' + item.desc + '"';

      if (chipsEl && item.chips) {
        chipsEl.innerHTML = '';
        var chipArr = item.chips.split(',');
        var colors = [
          { bg: 'var(--mint-light)', color: 'var(--mint-primary)' },
          { bg: 'var(--blue-light)', color: 'var(--blue-secondary)' },
          { bg: 'var(--orange-light)', color: 'var(--orange-tertiary)' },
          { bg: 'var(--purple-light)', color: 'var(--purple-leave)' }
        ];
        chipArr.forEach(function(chipText, cIdx) {
          var cScheme = colors[cIdx % colors.length];
          var span = document.createElement('span');
          span.style.background = cScheme.bg;
          span.style.color = cScheme.color;
          span.style.fontSize = '13px';
          span.style.fontWeight = '600';
          span.style.padding = '6px 14px';
          span.style.borderRadius = '99px';
          span.textContent = chipText.trim();
          chipsEl.appendChild(span);
        });
      }
    }

    function goToSlide(index) {
      if (index < 0) index = slides.length - 1;
      if (index >= slides.length) index = 0;
      currentIndex = index;

      slides.forEach(function(slide, idx) {
        if (idx === currentIndex) {
          slide.classList.add('active-slide');
        } else {
          slide.classList.remove('active-slide');
        }
      });

      var activeSlide = slides[currentIndex];
      if (activeSlide) {
        var scrollLeftPos = activeSlide.offsetLeft;
        track.scrollTo({ left: scrollLeftPos, behavior: 'smooth' });
      }

      if (dotsContainer) {
        var dots = dotsContainer.querySelectorAll('.wd-carousel-dot');
        dots.forEach(function(dot, idx) {
          if (idx === currentIndex) {
            dot.classList.add('active');
          } else {
            dot.classList.remove('active');
          }
        });
      }

      updateShowcaseText(currentIndex);
    }

    if (prevBtn) {
      prevBtn.addEventListener('click', function() {
        goToSlide(currentIndex - 1);
      });
    }

    if (nextBtn) {
      nextBtn.addEventListener('click', function() {
        goToSlide(currentIndex + 1);
      });
    }

    var isScrollingTimer = null;
    track.addEventListener('scroll', function() {
      clearTimeout(isScrollingTimer);
      isScrollingTimer = setTimeout(function() {
        var trackLeft = track.scrollLeft;
        var closestIdx = 0;
        var minDiff = Infinity;
        slides.forEach(function(slide, idx) {
          var diff = Math.abs(slide.offsetLeft - trackLeft);
          if (diff < minDiff) {
            minDiff = diff;
            closestIdx = idx;
          }
        });
        if (closestIdx !== currentIndex) {
          currentIndex = closestIdx;
          if (dotsContainer) {
            var dots = dotsContainer.querySelectorAll('.wd-carousel-dot');
            dots.forEach(function(dot, idx) {
              if (idx === currentIndex) dot.classList.add('active');
              else dot.classList.remove('active');
            });
          }
          updateShowcaseText(currentIndex);
        }
      }, 100);
    });

    window.onLanguageChanged = function(lang) {
      updateShowcaseText(currentIndex);
    };

    // Initialize first slide label
    updateShowcaseText(0);
  })();
});
